    cvss = vulnerability.get('CVSS')
    if not isinstance(cvss, dict):
        return 'N/A'
    for source in ('nvd', 'ghsa', 'redhat'):
        provider = cvss.get(source)
        if not isinstance(provider, dict):
            continue
        score = validated_v3_score(provider.get('V3Score'))
        if score is not None:
            return format(score, '.15g')
    return 'N/A'

records = []
for result_index, result in matching_results:
    vulnerabilities = result.get('Vulnerabilities')
    if vulnerabilities is None:
        continue
    if not isinstance(vulnerabilities, list):
        raise SystemExit(f'malformed Vulnerabilities in result {result_index}')
    for vulnerability_index, vulnerability in enumerate(vulnerabilities):
        if not isinstance(vulnerability, dict):
            raise SystemExit(f'malformed vulnerability at {result_index}:{vulnerability_index}')
        severity = vulnerability.get('Severity')
        if severity in allowed_severities:
            required = ('PkgName', 'InstalledVersion', 'VulnerabilityID')
            missing = [key for key in required if not isinstance(vulnerability.get(key), str) or not vulnerability.get(key)]
            if missing:
                raise SystemExit(f'missing required fields {missing} at {result_index}:{vulnerability_index}')
            record = {
                'Package': vulnerability['PkgName'],
                'Version': vulnerability['InstalledVersion'],
                'CVE_ID': vulnerability['VulnerabilityID'],
                'Severity': severity,
                'CVSS_Score': cvss_score(vulnerability),
                'Fixed_Version': scalar(vulnerability.get('FixedVersion')),
                'Title': scalar(vulnerability.get('Title') or vulnerability.get('Description')),
                'Url': scalar(vulnerability.get('PrimaryURL')),
            }
            pkg_identifier = vulnerability.get('PkgIdentifier')
            provenance = {
                'result_index': result_index,
                'target': result.get('Target'),
                'pkg_id': scalar(vulnerability.get('PkgID'), ''),
                'pkg_identifier': pkg_identifier if isinstance(pkg_identifier, dict) else {},
                'fingerprint': scalar(vulnerability.get('Fingerprint'), ''),
                'vulnerability_id': vulnerability['VulnerabilityID'],
            }
            records.append((record, provenance))

# Only byte-equivalent normalized records with the same finding provenance are duplicates.
deduplicated = {}
for record, provenance in records:
    key = (tuple(record[column] for column in columns), json.dumps(provenance, sort_keys=True, separators=(',', ':')))
    deduplicated[key] = (record, provenance)

ordered = sorted(deduplicated.values(), key=lambda item: (
    tuple(item[0][column] for column in columns),
    json.dumps(item[1], sort_keys=True, separators=(',', ':')),
))

with output_path.open('w', newline='', encoding='utf-8') as handle:
    writer = csv.DictWriter(handle, fieldnames=columns, lineterminator='\n')
    writer.writeheader()
    writer.writerows(record for record, _ in ordered)

# Post-parse validation of the actual written deliverable.
with output_path.open('r', newline='', encoding='utf-8') as handle:
    rows = list(csv.reader(handle))
if not rows or rows[0] != columns:
    raise SystemExit('CSV header mismatch')
if any(len(row) != len(columns) for row in rows[1:]):
    raise SystemExit('CSV row width mismatch')
expected_rows = [record for record, _ in ordered]
actual_rows = [dict(zip(columns, row)) for row in rows[1:]]
if actual_rows != expected_rows:
    raise SystemExit('CSV rows differ from normalized deterministic records')
if any(row['Severity'] not in allowed_severities for row in actual_rows):
    raise SystemExit('CSV contains a non-HIGH/CRITICAL row')
if any(not row['Package'] or not row['Version'] or not row['CVE_ID'] for row in actual_rows):
    raise SystemExit('CSV contains an empty required identity field')
if any(row['CVSS_Score'] == '' or row['Fixed_Version'] == '' or row['Title'] == '' or row['Url'] == '' for row in actual_rows):
    raise SystemExit('CSV contains an empty normalized optional field')
print('written=', output_path)
print('qualifying_records=', len(records))
print('deduplicated_records=', len(ordered))
print('csv_rows=', len(actual_rows))
